mapper.select:
select tbomdetail.id, tbomdetail.bom_id, tbomdetail.material_id, tbomdetail.count, tbomdetail.create_by, tbomdetail.create_time, tbomdetail.dept_name, m.code as materialCode, m.name as materialName, tu.name as unitName from t_bom_detail tbomdetail left join t_material m on tbomdetail.material_id = m.id left join t_unit tu on m.unit_id = tu.id
inner join sys_user u on u.user_name = tbomdetail.create_by and u.status = '0' inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'
tbomdetail.del_flag = '0' and tbomdetail.bom_id = #{bomId} and tbomdetail.count = #{count}
${params.dataScope}

select t1.id, t1.code, t1.name, t1.specifications, t1.batch_flag, t1.batch_attr_id, t1.base_unit_id, t1.same_material_flag, t1.same_batch_flag, t1.inspection_method, t1.expiration_date, t1.expiration_flag, t1.remark, t1.del_flag, t1.net_weight, t1.rough_weight, t2.name as unitName, tbomdetail.count as predictCount, ifnull(t3.library_count,0) as stockMin from t_bom_detail tbomdetail left join t_material t1 on tbomdetail.material_id = t1.id left join t_unit t2 on t1.unit_id = t2.id left join t_stock_main t3 on tbomdetail.material_id = t3.material_id where tbomdetail.del_flag = '0' and t1.del_flag = '0'
and tbomdetail.bom_id = #{bomId} and tbomdetail.id = #{id}
order by tbomdetail.create_time desc
